@push('scripts')<script>(()=>{const owner=document.getElementById('payoutOwner'),property=document.getElementById('payoutProperty'),invoice=document.getElementById('payoutInvoice');if(!owner||!property||!invoice)return;const sync=()=>{[...property.options].forEach((o,i)=>o.hidden=i>0&&!!owner.value&&o.dataset.owner!==owner.value);if(property.selectedOptions[0]?.hidden)property.value='';[...invoice.options].forEach((o,i)=>o.hidden=i>0&&!!property.value&&o.dataset.property!==property.value);if(invoice.selectedOptions[0]?.hidden)invoice.value='';};owner.addEventListener('change',sync);property.addEventListener('change',sync);sync();})();</script>@endpush
